    /// The checks step: the workspace's own test command, in the VM. A
    /// workspace with no command has nothing to run.
    pub(super) async fn checks_step(&self, record: &Record) -> Event {
        let ran = async {
            let workspaces = self.store.workspaces().await?;
            let command = workspaces
                .into_iter()
                .find(|w| w.name == record.job.workspace)
                .map(|w| w.checks)
                .unwrap_or_default();
            if command.trim().is_empty() {
                return Ok(Event::StepPassed);
            }
            let vm = Vm {
                engine: &*self.engine,
                sandbox: record.runtime.sandbox.as_deref().ok_or("no VM")?,
                spec: Spec { checks: Vec::new() },
            };
            Ok(acceptance::suite(&vm.run("checks", &command).await?))
        };
        ran.await
            .unwrap_or_else(|detail: String| Event::StepStuck { detail })
    }

    /// A workflow's command step (D35): its line in the repository.
    pub(super) async fn command_step(&self, record: &Record) -> Event {
        let ran = async {
            let line = record
                .job
                .step()
                .map(|s| s.run.clone())
                .ok_or("no command to run")?;
            let vm = Vm {
                engine: &*self.engine,
                sandbox: record.runtime.sandbox.as_deref().ok_or("no VM")?,
                spec: Spec { checks: Vec::new() },
            };
            Ok(acceptance::command(&vm.run(&line, &line).await?))
        };
        ran.await
            .unwrap_or_else(|detail: String| Event::StepStuck { detail })
    }

    async fn run_checks(&self) -> Result<Vec<Ran>, String> {
        let mut runs = Vec::new();
        for check in &self.spec.checks {
            runs.push(self.run(&check.criterion, &check.run).await?);
        }
        Ok(runs)
    }

    /// Run one command, whatever it exits with, and keep the end of its output.
    async fn run(&self, name: &str, command: &str) -> Result<Ran, String> {
        let out = self.exec(command, CHECK_SECS).await?;
        Ok(Ran {
            criterion: name.to_string(),
            code: out["exit_code"].as_i64().unwrap_or(-1),
            output: tail(&format!(
                "{}{}",
                out["stdout"].as_str().unwrap_or_default(),
                out["stderr"].as_str().unwrap_or_default()
            )),
        })
    }

    /// The spec's files as shell words.
    fn files(&self) -> String {
        quoted(&self.spec.files())
    }

    /// Run a shell line in the repository, and fail unless it exits 0.
    async fn sh(&self, line: &str) -> Result<String, String> {
        let out = self.exec(line, 120).await?;
        match out["exit_code"].as_i64() {
            Some(0) | None => Ok(out["stdout"].as_str().unwrap_or_default().to_string()),
            Some(code) => Err(format!("{line} exited {code}: {}", out["stderr"])),
        }
    }

    /// Run a shell line in the repository, whatever it exits with.
    async fn exec(&self, line: &str, secs: u64) -> Result<Value, String> {
        let argv = ["sh", "-c", &format!("cd {REPO} && {line}")];
        self.engine
            .call_for(
                DEFAULT_NAMESPACE,
                "sandbox::exec",
                json!({ "sandbox_id": self.sandbox, "argv": argv, "timeout_ms": secs * 1000 }),
                secs * 1000 + 60_000,
            )
            .await
    }
}

