/// A grant: what calls to a function pattern may do at one stage.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Capability {
    pub stage: Stage,
    pub function: String,
    pub rung: Access,
}

/// One call a turn makes. `text` is its arguments as the rules read them,
/// such as a command line or a path.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Call {
    pub function: String,
    pub text: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "decision")]
pub enum Decision {
    Continue,
    Deny {
        reason: String,
    },
    /// Wait for the owner: retry with feedback, allow this call once, or stop.
    Hold {
        reason: String,
    },
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Verdict {
    pub decision: Decision,
    /// The constraints at `checked` that the call breaks, for the record.
    pub flagged: Vec<String>,
}

/// `name` matches a pattern that equals it, or a pattern ending in `*` that
/// it starts with. The empty pattern matches nothing.
pub fn matches(pattern: &str, name: &str) -> bool {
    match pattern.strip_suffix('*') {
        Some(prefix) => !pattern.is_empty() && name.starts_with(prefix),
        None => !pattern.is_empty() && pattern == name,
    }
}

/// `text` holds every word of `words` in order, with any words between, so
/// `git rm` binds `git -C /work/repo rm a.py`. No words binds every text.
pub fn mentions(text: &str, words: &str) -> bool {
    let mut said = text.split_whitespace();
    words.split_whitespace().all(|w| said.any(|t| t == w))
}

/// The sandbox function that writes a file.
const WRITE: &str = "sandbox::fs::write";

/// Judge one call. A write to the charter is refused first, then any call
/// an enforced constraint binds. Then the most specific grant for the stage
/// decides, and a call no grant covers is refused.
pub fn gate(
    call: &Call,
    stage: Stage,
    constraints: &[Constraint],
    grants: &[Capability],
) -> Verdict {
    let broken = || {
        constraints
            .iter()
            .filter(|c| matches(&c.function, &call.function) && mentions(&call.text, &c.contains))
    };
    let flagged = broken()
        .filter(|c| c.rung == Enforcement::Checked)
        .map(|c| c.id.clone())
        .collect();
    let charter = (call.function == WRITE).then(|| crate::charter::guards(&call.text));
    let decision = if let Some(reason) = charter.flatten() {
        Decision::Deny { reason }
    } else if let Some(c) = broken().find(|c| c.rung == Enforcement::Enforced) {
        Decision::Deny {
            reason: format!("Refused by constraint {}: {}", c.id, c.rule),
        }
    } else {
        let grant = grants
            .iter()
            .filter(|g| g.stage == stage && matches(&g.function, &call.function))
            .max_by_key(|g| (!g.function.ends_with('*'), g.function.len()));
        match grant.map(|g| g.rung) {
            Some(Access::Allowed) => Decision::Continue,
            Some(Access::Ask) => Decision::Hold {
                reason: format!("{} at {stage:?} waits for the owner.", call.function),
            },
            Some(Access::Denied) => Decision::Deny {
                reason: format!("{} is not granted at {stage:?}.", call.function),
            },
            None => Decision::Deny {
                reason: format!("No grant covers {} at {stage:?}.", call.function),
            },
        }
    };
    Verdict { decision, flagged }
}

/// The rules `seed/governance.sql` writes, as values for tests. The running
/// factory reads its rules from the database (D26), never from here.
#[cfg(any(test, feature = "fixtures"))]
fn approved_test(file: &str) -> Constraint {
    Constraint {
        id: format!("approved-test:{file}"),
        rule: format!("Do not change {file}: it is an approved acceptance test."),
        function: "sandbox::fs::write".into(),
        contains: format!("/work/repo/{file}"),
        rung: bastion_core::govern::Enforcement::Enforced,
        source: bastion_core::govern::Source::Owner,
    }
}

/// What the rules read from a call: its command line in any of the shapes
/// `sandbox::exec` takes (`argv`, or `cmd` with `args`), else its path.
fn call_of(call: &Value) -> Call {
    let arguments = &call["arguments"];
    let words = |v: &Value| -> Vec<String> {
        v.as_array()
            .into_iter()
            .flatten()
            .filter_map(|w| w.as_str().map(String::from))
            .collect()
    };
    let mut line = words(&arguments["argv"]);
    if let Some(cmd) = arguments["cmd"].as_str() {
        line.push(cmd.into());
        line.extend(words(&arguments["args"]));
    }
    let text = if line.is_empty() {
        arguments["path"].as_str().unwrap_or_default().to_string()
    } else {
        line.join(" ")
    };
    Call {
        function: call["function_id"].as_str().unwrap_or_default().into(),
        text,
    }
}

